using WICareerBuilder.Data.Database;using WICareerBuilder.Data.Repositories;
namespace WICareerBuilder.Data.Tests;
[TestClass]
public sealed class CareerPortfolioApprovalTests
{
 [TestMethod] public async Task Migration0025_AdvancesFormatVersion(){await WithRepositoryAsync(async(db,_)=>{await using var c=await db.OpenConnectionAsync();var q=c.CreateCommand();q.CommandText="SELECT setting_value FROM settings WHERE setting_key='data_format_version';";var versionValue=Convert.ToString(await q.ExecuteScalarAsync());Assert.IsTrue(int.TryParse(versionValue,out var dataFormatVersion)&&dataFormatVersion>=25,$"Migration 0025 requires data format version >= 25; actual value was {versionValue ?? "<null>"}.");});}
 [TestMethod] public async Task CvApproval_RequiresPolicyRecommendation(){await WithRepositoryAsync(async(_,r)=>{var quiz=await r.CreateCareerEvidenceAsync("Quiz","InternalQuiz","Studied","Internal",null,null,false,true,"Reviewed","Private",true);await Assert.ThrowsExactlyAsync<InvalidOperationException>(()=>r.SetEvidenceCvApprovalAsync(quiz,true));var project=await r.CreateCareerEvidenceAsync("Bench test","ProjectTest","DemonstratedProject","Practical",null,null,true,true,"Reviewed","Private",true);await r.SetEvidenceCvApprovalAsync(project,true);Assert.IsTrue((await r.GetCareerEvidenceAsync()).Single(x=>x.Id==project).CvReadyUserApproved);});}
 [TestMethod] public async Task PortfolioDraft_IsPrivateAndNeverExportApprovedAutomatically(){await WithRepositoryAsync(async(_,r)=>{var project=await r.CreateCareerProjectAsync("WIHeart","Engineering","Research","Private",true);await r.SetProjectCareerEligibilityAsync(project,true,true);var id=await r.CreateCareerPortfolioEntryAsync(project,"WIHeart ECG","Signal acquisition","Working research prototype");var entry=(await r.GetCareerPortfolioEntriesAsync()).Single(x=>x.Id==id);Assert.AreEqual("Private",entry.PrivacyMode);Assert.IsFalse(entry.UserApprovedExport);Assert.AreEqual("Draft",entry.Status);});}
 private static async Task WithRepositoryAsync(Func<DatabaseService,LibraryRepository,Task> body){var root=Path.Combine(Path.GetTempPath(),"WICareerBuilder.Tests",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{var db=new DatabaseService(Path.Combine(root,"careerbuilder.db"));await db.InitializeAsync();await body(db,new LibraryRepository(db));}finally{try{Directory.Delete(root,true);}catch{}}}
}
